cat >> src/boxOffice.test.ts <<'EOF'

import { createBoxOffice, type BoxOfficeOptions } from "./boxOffice";

function setup(overrides: Partial<BoxOfficeOptions> = {}) {
  let time = 1_000_000;
  const clock = {
    advanceMinutes(minutes: number) {
      time += minutes * 60_000;
    },
    get time() {
      return time;
    },
  };
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 5000 },
      { id: "BALKON", capacity: 5, priceCents: 3333 },
    ],
    holdMinutes: 10,
    maxTicketsPerCustomer: 6,
    now: () => time,
    ...overrides,
  });
  return { office, clock };
}

function codeOf(fn: () => unknown): string | undefined {
  try {
    fn();
  } catch (e) {
    if (e instanceof BoxOfficeError) return e.code;
    throw e;
  }
  return undefined;
}

describe("available", () => {
  test("is the capacity of a fresh section", () => {
    const { office } = setup();
    expect(office.available("PARKETT")).toBe(10);
    expect(office.available("BALKON")).toBe(5);
  });
});
EOF
bun test 2>&1 | tail -5

